function parseFragment(): { query: string; noteId: number | null } {
  const hash = window.location.hash.slice(1);
  const params = new URLSearchParams(hash);
  return {
    query: params.get('q') || '',
    noteId: params.has('note') ? parseInt(params.get('note')!, 10) : null
  };
