// Parse and render rich text safely - only allows specific tags
function renderRichText(text: string, container: HTMLElement): void {
  container.textContent = '';

  // Convert newlines to <br>
  let html = text.replace(/\n/g, '<br>');

  // Parse allowed tags manually
  const tagPattern = /<(\/?)(\w+)(\s+[^>]*)?>/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = tagPattern.exec(html)) !== null) {
    const beforeTag = html.slice(lastIndex, match.index);
    if (beforeTag) {
      container.appendChild(document.createTextNode(beforeTag));
    }

    const isClosing = match[1] === '/';
    const tagName = (match[2] || '').toLowerCase();
    const attributes = match[3] || '';

    if (!isClosing) {
      if (tagName === 'br') {
        container.appendChild(document.createElement('br'));
      } else if (tagName === 'b' || tagName === 'strong') {
        const elem = document.createElement(tagName);
        // Find closing tag and recursively parse content
        const closingPattern = new RegExp(`</${tagName}>`, 'i');
        const remaining = html.slice(match.index + match[0].length);
        const closingMatch = closingPattern.exec(remaining);
        if (closingMatch) {
          const content = remaining.slice(0, closingMatch.index);
          renderRichText(content, elem);
          container.appendChild(elem);
          tagPattern.lastIndex = match.index + match[0].length + closingMatch.index + closingMatch[0].length;
        }
      } else if (tagName === 'i' || tagName === 'em') {
        const elem = document.createElement(tagName);
        const closingPattern = new RegExp(`</${tagName}>`, 'i');
        const remaining = html.slice(match.index + match[0].length);
        const closingMatch = closingPattern.exec(remaining);
        if (closingMatch) {
          const content = remaining.slice(0, closingMatch.index);
          renderRichText(content, elem);
          container.appendChild(elem);
          tagPattern.lastIndex = match.index + match[0].length + closingMatch.index + closingMatch[0].length;
        }
      } else if (tagName === 'a') {
        const elem = document.createElement('a');
        // Extract href attribute
        const hrefMatch = /href=["']([^"']+)["']/.exec(attributes);
        if (hrefMatch && hrefMatch[1]) {
          elem.href = hrefMatch[1];
        }
        const closingPattern = /<\/a>/i;
        const remaining = html.slice(match.index + match[0].length);
        const closingMatch = closingPattern.exec(remaining);
        if (closingMatch) {
          const content = remaining.slice(0, closingMatch.index);
          renderRichText(content, elem);
          container.appendChild(elem);
          tagPattern.lastIndex = match.index + match[0].length + closingMatch.index + closingMatch[0].length;
        }
      }
    }

    lastIndex = tagPattern.lastIndex;
  }

  // Add remaining text
  const remaining = html.slice(lastIndex);
  if (remaining) {
    container.appendChild(document.createTextNode(remaining));
  }
}

